import React, { useEffect, useState } from "react";
import axios from "../utils/axios";
import { Trash2 } from "lucide-react";
import ConfirmDeleteModal from "../components/ConfirmDeleteModal";

const AllExpenses = () => {
  const [expenses, setExpenses] = useState([]);
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState("");
  const [deleteId, setDeleteId] = useState(null);
  const PER_PAGE = 12;

  const fetch = async () => {
    try {
      const email = localStorage.getItem("email");
      const r = await axios.get("/api/expenses", { headers: { email } });
      const sorted = (Array.isArray(r.data) ? r.data : []).sort((a, b) => new Date(b.date) - new Date(a.date));
      setExpenses(sorted);
    } catch (e) { console.error(e); }
  };

  useEffect(() => { fetch(); }, []);

  const handleDelete = async () => {
    await axios.delete(`/api/expenses/${deleteId}`, { headers: { email: localStorage.getItem("email") } });
    setDeleteId(null);
    fetch();
  };

  const filtered = expenses.filter(e =>
    !search || e.description?.toLowerCase().includes(search.toLowerCase()) || e.budget?.name?.toLowerCase().includes(search.toLowerCase())
  );
  const total = filtered.reduce((s, e) => s + (e.amount || 0), 0);
  const totalPages = Math.max(1, Math.ceil(filtered.length / PER_PAGE));
  const current = filtered.slice((page - 1) * PER_PAGE, page * PER_PAGE);

  return (
    <div style={{ fontFamily: "'Inter', sans-serif" }}>
      <div style={{ marginBottom: 32 }}>
        <div style={{ fontSize: 11, color: "#9b9b9b", letterSpacing: "0.06em", textTransform: "uppercase", marginBottom: 6 }}>Finance</div>
        <h1 style={{ fontSize: 28, fontWeight: 700, color: "#191919", margin: 0, letterSpacing: "-0.03em" }}>All Expenses</h1>
        <p style={{ fontSize: 14, color: "#6b6b6b", marginTop: 6 }}>Complete transaction history</p>
      </div>

      {/* Summary + Search */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
        <div style={{ display: "flex", gap: 16 }}>
          <div style={{ padding: "10px 16px", background: "#eff6ff", borderRadius: 8, border: "1px solid #bfdbfe" }}>
            <div style={{ fontSize: 11, color: "#3b82f6", fontWeight: 500, textTransform: "uppercase", letterSpacing: "0.06em" }}>Total</div>
            <div style={{ fontSize: 18, fontWeight: 700, color: "#1d4ed8" }}>RM {total.toFixed(2)}</div>
          </div>
          <div style={{ padding: "10px 16px", background: "#fafaf9", borderRadius: 8, border: "1px solid #e8e8e6" }}>
            <div style={{ fontSize: 11, color: "#9b9b9b", fontWeight: 500, textTransform: "uppercase", letterSpacing: "0.06em" }}>Transactions</div>
            <div style={{ fontSize: 18, fontWeight: 700, color: "#191919" }}>{filtered.length}</div>
          </div>
        </div>
        <input
          type="text" placeholder="Search…" value={search}
          onChange={e => { setSearch(e.target.value); setPage(1); }}
          style={{ padding: "9px 14px", border: "1px solid #e8e8e6", borderRadius: 8, fontSize: 14, width: 220, outline: "none", fontFamily: "'Inter', sans-serif", color: "#191919" }}
          onFocus={e => e.target.style.borderColor = "#2563eb"}
          onBlur={e => e.target.style.borderColor = "#e8e8e6"}
        />
      </div>

      <div style={{ background: "#fff", border: "1px solid #e8e8e6", borderRadius: 10, overflow: "hidden" }}>
        {current.length === 0 ? (
          <div style={{ padding: "60px 0", textAlign: "center", color: "#9b9b9b", fontSize: 13 }}>
            {search ? "No results found" : "No expenses yet"}
          </div>
        ) : (
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ background: "#fafaf9" }}>
                {["Budget", "Description", "Amount", "Date", ""].map(h => (
                  <th key={h} style={{ padding: "10px 20px", fontSize: 11, fontWeight: 600, color: "#9b9b9b", textTransform: "uppercase", letterSpacing: "0.06em", textAlign: h === "Amount" || h === "Date" ? "right" : "left", whiteSpace: "nowrap" }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {current.map(e => (
                <tr key={e.id} style={{ borderTop: "1px solid #f1f1ef" }}>
                  <td style={{ padding: "13px 20px" }}>
                    <span style={{ background: "#f1f1ef", borderRadius: 5, padding: "3px 8px", fontSize: 12, color: "#374151", whiteSpace: "nowrap" }}>
                      {e.budget?.icon} {e.budget?.name || "—"}
                    </span>
                  </td>
                  <td style={{ padding: "13px 20px", fontSize: 14, color: "#191919" }}>{e.description}</td>
                  <td style={{ padding: "13px 20px", textAlign: "right", fontSize: 14, fontWeight: 600, color: "#191919", whiteSpace: "nowrap" }}>RM {(e.amount||0).toFixed(2)}</td>
                  <td style={{ padding: "13px 20px", textAlign: "right", fontSize: 13, color: "#9b9b9b", whiteSpace: "nowrap" }}>
                    {e.date ? new Date(e.date).toLocaleDateString("en-MY", { day: "numeric", month: "short", year: "numeric" }) : "—"}
                  </td>
                  <td style={{ padding: "13px 20px", textAlign: "right" }}>
                    <button onClick={() => setDeleteId(e.id)} style={{ background: "none", border: "none", color: "#d1d5db", cursor: "pointer", padding: 4, borderRadius: 4 }}
                      onMouseEnter={e2 => e2.currentTarget.style.color = "#dc2626"}
                      onMouseLeave={e2 => e2.currentTarget.style.color = "#d1d5db"}>
                      <Trash2 size={14} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
        {totalPages > 1 && (
          <div style={{ padding: "12px 20px", borderTop: "1px solid #f1f1ef", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1} style={pgBtn}>← Prev</button>
            <span style={{ fontSize: 13, color: "#9b9b9b" }}>Page {page} of {totalPages}</span>
            <button onClick={() => setPage(p => Math.min(totalPages, p + 1))} disabled={page === totalPages} style={pgBtn}>Next →</button>
          </div>
        )}
      </div>

      <ConfirmDeleteModal isOpen={!!deleteId} onClose={() => setDeleteId(null)} onConfirm={handleDelete} message="Delete this expense?" />
    </div>
  );
};

const pgBtn = { background: "none", border: "1px solid #e8e8e6", color: "#374151", fontSize: 13, padding: "5px 12px", borderRadius: 6, cursor: "pointer", fontFamily: "'Inter', sans-serif" };

export default AllExpenses;
